import { describe, it, expect } from 'vitest';
import { getBreakpoints } from './images-optimization';

const imageSizes = [16, 32, 48, 64, 96, 128, 256, 384];
const deviceSizes = [640, 750, 828, 960, 1080, 1280, 1668, 1920, 2048, 2560, 3200, 3840, 4480, 5120, 6016];

describe('getBreakpoints', () => {
  describe('narrow images (width < smallest deviceSize)', () => {
    it('uses imageSizes for fullWidth layout when image is narrower than 640px', () => {
      const result = getBreakpoints({ layout: 'fullWidth', imageWidth: 300 });
      expect(result).toEqual(imageSizes);
    });

    it('uses imageSizes for responsive layout when image is narrower than 640px', () => {
      const result = getBreakpoints({ layout: 'responsive', imageWidth: 500 });
      expect(result).toEqual(imageSizes);
    });

    it('uses imageSizes for cover layout when image is narrower than 640px', () => {
      const result = getBreakpoints({ layout: 'cover', imageWidth: 100 });
      expect(result).toEqual(imageSizes);
    });

    it('uses imageSizes for contained layout when image is narrower than 640px', () => {
      const result = getBreakpoints({ layout: 'contained', imageWidth: 400 });
      expect(result).toEqual(imageSizes);
    });

    it('uses imageSizes in constrained layout fallback when image is narrower than 640px', () => {
      const result = getBreakpoints({ width: 300, layout: 'constrained', imageWidth: 300 });
      // Should include width, doubleWidth, and filtered imageSizes (all < 600)
      expect(result).toContain(300);
      expect(result).toContain(600);
      // Should NOT contain any deviceSizes
      for (const ds of deviceSizes) {
        expect(result).not.toContain(ds);
      }
      // Should contain imageSizes that are < doubleWidth (600)
      expect(result).toContain(384);
      expect(result).toContain(256);
    });
  });

  describe('wide images (width >= smallest deviceSize)', () => {
    it('uses deviceSizes for fullWidth layout when image is wider than 640px', () => {
      const result = getBreakpoints({ layout: 'fullWidth', imageWidth: 1920 });
      expect(result).toEqual(deviceSizes);
    });

    it('uses deviceSizes for fullWidth layout when no imageWidth is provided', () => {
      const result = getBreakpoints({ layout: 'fullWidth' });
      expect(result).toEqual(deviceSizes);
    });

    it('uses deviceSizes for constrained layout when image is wider than 640px', () => {
      const result = getBreakpoints({ width: 800, layout: 'constrained', imageWidth: 1920 });
      expect(result).toContain(800);
      expect(result).toContain(1600);
      // Should contain deviceSizes that are < doubleWidth
      expect(result).toContain(640);
      expect(result).toContain(750);
      expect(result).toContain(828);
      expect(result).toContain(960);
      expect(result).toContain(1080);
      expect(result).toContain(1280);
    });
  });

  describe('fixed layout (unaffected by imageWidth)', () => {
    it('returns [width, doubleWidth] regardless of imageWidth', () => {
      const result = getBreakpoints({ width: 200, layout: 'fixed', imageWidth: 200 });
      expect(result).toEqual([200, 400]);
    });
  });

  describe('edge case: imageWidth exactly at smallest deviceSize boundary', () => {
    it('uses deviceSizes when imageWidth equals 640', () => {
      const result = getBreakpoints({ layout: 'fullWidth', imageWidth: 640 });
      expect(result).toEqual(deviceSizes);
    });

    it('uses imageSizes when imageWidth is 639', () => {
      const result = getBreakpoints({ layout: 'fullWidth', imageWidth: 639 });
      expect(result).toEqual(imageSizes);
    });
  });
});

