export const getBreakpoints = ({
  width,
  breakpoints,
  layout,
  imageWidth,
}: {
  width?: number;
  breakpoints?: number[];
  layout: Layout;
  imageWidth?: number;
}): number[] => {
  const smallestDeviceSize = config.deviceSizes[0];
  const isNarrow = imageWidth !== undefined && imageWidth < smallestDeviceSize;
  const defaultSizes = isNarrow ? config.imageSizes : config.deviceSizes;

  if (layout === 'fullWidth' || layout === 'cover' || layout === 'responsive' || layout === 'contained') {
    return breakpoints || defaultSizes;
  }
  if (!width) {
    return [];
  }
  const doubleWidth = width * 2;
  if (layout === 'fixed') {
    return [width, doubleWidth];
  }
  if (layout === 'constrained') {
    return [
      // Always include the image at 1x and 2x the specified width
      width,
      doubleWidth,
      // Filter out any resolutions that are larger than the double-res image
      ...(breakpoints || defaultSizes).filter((w) => w < doubleWidth),
    ];
  }

  return [];
};

